// spec: specs/landing-footer.md
// seed: tests/seed.spec.ts

import { test, expect } from '@playwright/test';

const networks: Record<string, RegExp> = {
  youtube: /(^|\.)youtube\.com$|(^|\.)youtu\.be$/,
  instagram: /(^|\.)instagram\.com$/,
  tiktok: /(^|\.)tiktok\.com$/,
  facebook: /(^|\.)facebook\.com$|(^|\.)fb\.com$/,
  linkedin: /(^|\.)linkedin\.com$/,
};

test.describe('Landing footer and about links', () => {
  test('Footer social icons are real profiles or hidden @desktop @prod-safe (#1afa56)', async ({ page }) => {
    for (const path of ['/', '/about']) {
      // 1. Open the page as guest and scroll to the footer
      await page.goto(path);
      const footer = page.getByRole('contentinfo');
      await footer.scrollIntoViewIfNeeded();
      await expect(footer).toBeVisible();

      // 2. Collect footer links mentioning a social network (by accessible name or href)
      const links = await footer.locator('a').evaluateAll((els) =>
        els.map((a) => ({
          name: `${a.getAttribute('aria-label') ?? ''} ${a.textContent ?? ''}`,
          href: a.getAttribute('href') ?? '',
          target: a.getAttribute('target') ?? '',
          rel: a.getAttribute('rel') ?? '',
        })),
      );
      const social = links.filter((l) => /youtube|instagram|tiktok|facebook|linkedin/i.test(`${l.name} ${l.href}`));

      // Zero such links is valid; otherwise each must be a real https profile that opens in a new tab
      for (const l of social) {
        expect(l.href, `href on ${path}`).toMatch(/^https:\/\//);
        const host = new URL(l.href).hostname;
        const key = Object.keys(networks).find((k) => new RegExp(k, 'i').test(`${l.name} ${l.href}`))!;
        expect(host, `domain of ${l.href}`).toMatch(networks[key]);
        expect(l.target).toBe('_blank');
        expect(l.rel).toContain('noopener');
      }
    }
  });
});
